var DATA = {"signal": "checkout p99 latency", "baseline": "400 ms", "series": "400|410|395|3200|405|398", "causes": "Cron contention|cache stampede|downstream slowdown"};
console.log("Signal: " + DATA.signal + " | Baseline: " + DATA.baseline);
var vals = DATA.series.split("|").map(function (s) { return parseFloat(s); });
var mean = vals.reduce(function (a, b) { return a + b; }, 0) / vals.length;
var sd = Math.sqrt(vals.reduce(function (a, b) { return a + (b - mean) * (b - mean); }, 0) / vals.length);
console.log("mean=" + mean.toFixed(2) + " sd=" + sd.toFixed(2));
var anomalies = 0;
vals.forEach(function (v, i) {
  var z = sd === 0 ? 0 : Math.abs((v - mean) / sd);
  var anom = z > 2.5;
  if (anom) anomalies++;
  console.log("  t" + i + ": " + v + " (z=" + z.toFixed(2) + ")" + (anom ? "  <-- ANOMALY" : ""));
});
console.log("Likely causes: " + DATA.causes);
console.log("RESULT: " + anomalies + "/" + vals.length + " anomalous points detected.");

